import re

def parse_duration(s: str) -> int:
    s = s.strip()
    if not s:
        raise ValueError("Empty or invalid string")

    # Validate that the string contains only digits and unit characters h, m, s
    if not re.match(r'^[\d+hms]*$', s):
        raise ValueError("Invalid string format")

    pattern = re.compile(r'(\d+)([hms])')
    matches = pattern.findall(s)

    if not matches:
        raise ValueError("Invalid string format")

    total_seconds = 0
    for num_str, unit in matches:
        num = int(num_str)
        if unit == 'h':
            total_seconds += num * 3600
        elif unit == 'm':
            total_seconds += num * 60
        elif unit == 's':
            total_seconds += num

    return total_seconds
