def parse_headers(raw: str) -> dict[str, str]:
    """Parse HTTP header lines from raw string into a case-normalized dict."""
    lines = raw.splitlines()
    result: dict[str, str] = {}

    for line in lines:
        # Skip blank lines
        if not line.strip():
            continue

        # A line without ':' raises ValueError
        if ':' not in line:
            raise ValueError(f"Line does not contain ':' : '{line}'")

        # Only the first ':' separates name and value
        colon_idx = line.index(':')
        name = line[:colon_idx].lower()
        value = line[colon_idx + 1:].strip()

        # Repeating header names are joined with ', ' in order of appearance
        if name in result:
            result[name] += ', ' + value
        else:
            result[name] = value

    return result
