def allocate(total_cents: int, weights: list[int]) -> list[int]:
    if total_cents < 0:
        raise ValueError("total_cents must be non-negative")
    if not weights:
        raise ValueError("weights cannot be empty")
    for w in weights:
        if w < 0:
            raise ValueError("weight cannot be negative")
    total_weight = sum(weights)
    if total_weight == 0:
        raise ValueError("total weight cannot be zero (all weights are zero)")

    base_shares = [int(total_cents * w / total_weight) for w in weights]
    remainder = total_cents - sum(base_shares)

    if remainder > 0:
        extra_indices = sorted(
            range(len(weights)),
            key=lambda i: (-((total_cents * weights[i]) % total_weight), i)
        )
        for idx in extra_indices[:remainder]:
            base_shares[idx] += 1

    return base_shares
