def parse_brl(s: str) -> Decimal:
    # Strip leading/trailing whitespace
    s = s.strip()

    if not s:
        raise ValueError("Empty string")

    # Check for surrounding parentheses (negative)
    negative = False
    if len(s) >= 2 and s[0] == '(' and s[-1] == ')':
        negative = True
        s = s[1:-1].strip()

    # Check for leading minus sign
    if not negative:
        if s.startswith('-'):
            negative = True
            s = s[1:].strip()
        else:
            s = s.strip()

    if negative and not s:
        raise ValueError("Empty string after sign")

    # Remove 'R$' prefix if present
    if s.startswith('R$'):
        s = s[2:]
    s = s.strip()

    # Check for R$ without proper number following
    if not s or s == '' or (s.startswith('R$') and not any(c.isdigit() or c in '.,' for c in s)):
        raise ValueError("Invalid format")

    # Validate allowed characters
    valid_chars = set('0123456789.,-')
    if negative:
        valid_chars.discard('-')
    for c in s:
        if c not in valid_chars:
            raise ValueError(f"Invalid character: {c}")

    # Determine if there's a comma (cents separator)
    comma_pos = s.find(',')
    if comma_pos == -1:
        integer_part = s
        cents = None
    else:
        integer_part = s[:comma_pos]
        cents_part = s[comma_pos + 1:]

    # Validate cents part if present
    if cents is None and cents_part != '':
        if len(cents_part) != 2 or not cents_part.isdigit():
            raise ValueError("Cents must be exactly 2 digits")
    elif cents_part == '' and integer_part == '':
        raise ValueError("Invalid format")

    # Validate integer part (may contain '.' as thousand separator)
    if not integer_part or not integer_part.replace('.', '').replace('-', ''):
        raise ValueError("No valid digits in integer part")

    # Remove any thousands separators and validate resulting digits
    digits_only = integer_part.replace('.', '').replace(',', '')

    # Validate that '.' only appears as thousand separator (groups of 3)
    if '.' in integer_part:
        parts = integer_part.split('.')
        # Check we don't have multiple dots or invalid placements
        if len(parts) != 2:
            raise ValueError(f"Multiple dot separators not allowed")

        int_part_no_sep = parts[0]
        frac_part = parts[1]

        # Each group after the first must be exactly 3 digits
        for i, p in enumerate(parts):
            if not p.isdigit():
                raise ValueError(f"Non-digit in integer part: {p}")
            if i == 0:
                continue  # First group may have any length (plain number)
            if len(p) != 3:
                raise ValueError("Thousand groups must be exactly 3 digits")

    # Clean up the integer part - remove all dots for value calculation
    int_value = int(digits_only) if not cents else int(digits_only.lstrip('-'))

    # Reconstruct with proper Decimal conversion
    if cents is not None:
        return Decimal(f"{int_value}.{cents_part}") * (-1) if negative else Decimal(f"{int_value}.{cents_part}")
    else:
        result = Decimal(int_value)
