def compare_versions(a: str, b: str) -> int:
    def parse_version(version: str):
        if '+' in version:
            version = version.split('+')[0]

        if '-' in version:
            base, pre = version.rsplit('-', 1)
        else:
            base, pre = version, ''

        parts = base.split('.')
        major = int(parts[0]) if len(parts) > 0 else 0
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        pre_ids = []
        if pre:
            for id in pre.split('.'):
                try:
                    pre_ids.append((True, int(id)))
                except ValueError:
                    pre_ids.append((False, id))

        return (major, minor, patch, pre_ids)

    a_parsed = parse_version(a)
    b_parsed = parse_version(b)

    maj_a, min_a, pat_a, pre_a = a_parsed
    maj_b, min_b, pat_b, pre_b = b_parsed

    for val1, val2 in [(maj_a, maj_b), (min_a, min_b), (pat_a, pat_b)]:
        if val1 < val2:
            return -1
        elif val1 > val2:
            return 1

    pre_a_list = list(pre_a) if pre_a else []
    pre_b_list = list(pre_b) if pre_b else []

    for i in range(max(len(pre_a_list), len(pre_b_list))):
        ia, va = pre_a_list[i] if i < len(pre_a_list) else (False, None)
        ib, vb = pre_b_list[i] if i < len(pre_b_list) else (False, None)

        if ia != ib:
            if ia and not ib:
                return 1
            elif ib and not ia:
                return -1
            elif isinstance(va, int) and isinstance(vb, int):
                if va < vb:
                    return -1
                elif va > vb:
                    return 1
            else:
                s1 = str(va) if not isinstance(va, int) else str(va)
                s2 = str(vb) if not isinstance(vb, int) else str(vb)
                if s1 < s2:
                    return -1
                elif s1 > s2:
                    return 1

    return 0
