def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Collect all items (both keys/defined items and values/dependencies)
    all_items = set(deps.keys()) | set(deps.values())

    # Build in-degree count for each item
    in_degree = {item: 0 for item in all_items}
    dependents_of = {}  # maps a dependency to the items that depend on it

    for item, dependencies in deps.items():
        for dep in dependencies:
            in_degree[item] += 1
            if dep not in dependents_of:
                dependents_of[dep] = []
            dependents_of[dep].append(item)

    # Kahn's algorithm with alphabetical ordering at each step
    ready = sorted([item for item in all_items if in_degree[item] == 0])
    result = []

    while ready:
        current = ready.pop(0)
        result.append(current)

        if current in dependents_of:
            for dependent in dependents_of[current]:
                in_degree[dependent] -= 1
                if in_degree[dependent] == 0:
                    ready.append(dependent)
                    ready.sort()

        if len(result) < len(all_items):
            raise ValueError("Cycle detected")

    return result
