def wrap(text: str, width: int) -> list[str]:
    words = re.findall(r'\S+', text)
    if not words:
        return []

    result = []
    current_line = []
    current_len = 0

    for word in words:
        if len(word) > width:
            pieces = [word[i:i + width] for i in range(0, len(word), width)]
            for piece in pieces:
                if not current_line and current_len == 0:
                    current_line.append(piece)
                    current_len = len(piece)
                elif current_len + 1 + len(piece) <= width:
                    current_line.append(piece)
                    current_len += 1 + len(piece)
                else:
                    result.append(' '.join(current_line))
                    current_line = [piece]
                    current_len = len(piece)
        else:
            if not current_line and current_len == 0:
                current_line.append(word)
                current_len = len(word)
            elif current_len + 1 + len(word) <= width:
                current_line.append(word)
                current_len += 1 + len(word)
            else:
