from typing import Any

def latest_by_key(records: list[dict], key: str) -> list[dict]:
    first_appearance_order = []
    seen_keys = set()
    best_record = {}  # key_value -> (record, index)

    for i, record in enumerate(records):
        k_val = record[key]
        if k_val not in seen_keys:
            first_appearance_order.append(k_val)
            seen_keys.add(k_val)

        try:
            ts_str = record['updated_at']
            if ts_str.endswith('Z'):
                ts_str = ts_str[:-1] + '+00:00'
            updated_at = datetime.fromisoformat(ts_str).replace(tzinfo=timezone.utc)
        except (KeyError, ValueError):
            # Skip records without valid updated_at for comparison purposes
            continue

        if k_val not in best_record:
            best_record[k_val] = (record, i)
        else:
            curr_rec, curr_idx = best_record[k_val]
            curr_ts = datetime.fromisoformat(
                curr_rec['updated_at'].rstrip('Z') + '+00:00'
            ).replace(tzinfo=timezone.utc)

            # New record is better if its timestamp is strictly greater,
            # or equal (tie) -> pick the one later in the list.
            if updated_at > curr_ts:
                best_record[k_val] = (record, i)
            elif updated_at == curr_ts and i > curr_idx:
                best_record[k_val] = (record, i)

    # Collect results in first-appearance order of each key value
    result = []
    seen = set()
    for k_val in first_appearance_order:
        if k_val not in seen:
            rec, _ = best_record.get(k_val)
            if rec is not None:
                result.append(rec)
            seen.add(k_val)

    return result
