def natural_sorted(names: list[str]) -> list[str]:
    def to_key(name: str):
        parts = []
        i = 0
        n = len(name)
        while i < n:
            if name[i].isdigit():
                j = i
                while j < n and name[j].isdigit():
                    j += 1
                parts.append((True, int(name[i:j])))
                i = j
            else:
                j = i
                while j < n and not name[j].isdigit():
                    j += 1
                parts.append((False, name[i:j].lower()))
                i = j
        return tuple(parts)

    def compare(a: str, b: str) -> int:
        ka = to_key(a)
        kb = to_key(b)
        for x, y in zip(ka, kb):
            vx = x[1] if isinstance(x, tuple) else x
            vy = y[1] if isinstance(y, tuple) else y
            if type(vx) != type(vy):
                # Text before number when types differ at same position
                return -1 if not isinstance(vx, int) else 1
            if vx < vy:
                return -1
            elif vx > vy:
                return 1
        if len(ka) != len(kb):
            return -1 if len(ka) < len(kb) else 1
        return 0

    return sorted(names, key=cmp_to_key(compare))
