def allocate(total_cents: int, weights: list[int]) -> list[int]:
    if total_cents < 0:
        raise ValueError("total_cents must be non-negative")
    if not weights:
        raise ValueError("weights cannot be empty")
    if any(w < 0 for w in weights):
        raise ValueError("all weights must be non-negative")
    if sum(weights) == 0:
        raise ValueError("at least one weight must be positive")

    W = sum(weights)
    result = []
    remainders = []

    for w in weights:
        share = (total_cents * w) // W
        remainder = (total_cents * w) / W - share
        result.append(share)
        remainders.append(remainder)

    leftover = total_cents - sum(result)
    if leftover > 0:
        # Sort indices by remainder descending, then ascending for ties
        remaining_indices = list(range(len(weights)))
        remaining_indices.sort(key=lambda i: (-remainders[i], i))
        for idx in remaining_indices:
            if leftover == 0:
                break
            result[idx] += 1
            leftover -= 1

    return result
