import re

def parse_brl(s: str) -> Decimal:
    s = s.strip()
    if not s:
        raise ValueError("Empty string")

    is_negative = False
    original = s

    if s.startswith('-'):
        is_negative = True
        s = s[1:]
    elif s.startswith('('):
        is_negative = True
        if not s.endswith(')'):
            raise ValueError("Mismatched parentheses")
        s = s[1:-1]

    # Remove R$ prefix and surrounding spaces
    s = s.strip()
    s = re.sub(r'^R$', '', s, flags=re.IGNORECASE)
    s = re.sub(r'^R\$', '', s)

    if not re.match(r'^[0-9]*\.[0-9]{1,3}(\.[0-9]{3})*$|^[0-9]+$', s):
        raise ValueError(f"Invalid integer part: {original}")

    # Split by comma for cents
    parts = s.split(',')
    if len(parts) == 1:
        int_part = parts[0]
        cents = '00'
    else:
        int_part = parts[0]
        cents = parts[1]

    # Validate integer part groups
    if '.' in int_part:
        groups = int_part.split('.')
        if len(groups) != 2:
            raise ValueError(f"Invalid integer part: {original}")
        if not re.match(r'^\d{1,3}$', groups[0]):
            raise ValueError(f"Invalid integer part: {original}")
        if len(groups[1]) != 3:
            raise ValueError(f"Invalid integer part: {original}")
        int_part = groups[0] + groups[1]
    else:
        if not re.match(r'^\d+$', int_part):
            raise ValueError(f"Invalid integer part: {original}")

    # Validate cents
    if len(cents) != 2 or not cents.isdigit():
        raise ValueError(f"Cents must be exactly 2 digits: {original}")

    try:
        value = Decimal(int_part) + Decimal(cents) / Decimal('100')
    except:
        raise ValueError(f"Invalid decimal conversion: {original}")

    if is_negative:
        value = -value

    return value
