            return 0
        elif pra_a is None:
            return 1      # release > prerelease
        elif pra_b is None:
            return -1     # release < prerelease

        ids_a = pra_a.split('.')
        ids_b = pra_b.split('.')

        max_len = max(len(ids_a), len(ids_b))
        for i in range(max_len):
            id_a = ids_a[i] if i < len(ids_a) else ''
            id_b = ids_b[i] if i < len(ids_b) else ''

            a_num = is_numeric_only(id_a)
            b_num = is_numeric_only(id_b)

            # Both are numeric identifiers: compare as integers
            if a_num and b_num:
                int_a = int(id_a)
                int_b = int(id_b)
                if int_a < int_b:
                    return -1
                elif int_a > int_b:
                    return 1
            # Both are alphanumeric (or non-numeric): compare lexicographically
            elif not a_num and not b_num:
                if id_a < id_b:
                    return -1
                elif id_a > id_b:
                    return 1
            # Numeric vs alphanumeric: numeric is considered lower
            elif a_num:
                return -1
            else:
                return 1

        # All compared identifiers were equal; shorter list is lower
        if len(ids_a) < len(ids_b):
            return -1
        elif len(ids_a) > len(ids_b):
            return 1
        return 0

