from datetime import datetime

def latest_by_key(records: list[dict], key: str) -> list[dict]:
    def parse_iso(dt_str: str) -> datetime:
        if dt_str.endswith('Z'):
            dt_str = dt_str[:-1] + '+00:00'
        return datetime.fromisoformat(dt_str)

    # Track the order in which each key value first appears
    key_order = []
    seen_keys = set()
    for record in records:
        k = record[key]
        if k not in seen_keys:
            key_order.append(k)
            seen_keys.add(k)

    # Find the latest record per key value, with tie-breaking by later list index
    key_to_record = {}
    for i, record in enumerate(records):
        k = record[key]
        ts = parse_iso(record['updated_at'])

        if k not in key_to_record:
            key_to_record[k] = (ts, i, record)
        else:
            existing_ts, existing_i, _ = key_to_record[k]
            if ts > existing_ts or (ts == existing_ts and i > existing_i):
                key_to_record[k] = (ts, i, record)

    # Return the selected records in order of first key appearance
    return [key_to_record[k][2] for k in key_order]
