    except ValueError:
        return False

    for net_str in networks:
        if '/' not in net_str:
            raise ValueError(f"Invalid network '{net_str}': missing CIDR notation")

        try:
            if ':' in net_str and '::ffff:' in net_str:
                network = ipaddress.IPv6Network(net_str, strict=False)
            elif ':' in net_str:
                network = ipaddress.IPv6Network(net_str, strict=False)
            else:
                network = ipaddress.IPv4Network(net_str, strict=False)
        except ValueError as e:
            raise ValueError(f"Invalid network '{net_str}': {e}")

        # Check IPv4-mapped IPv6 addresses against IPv4 networks
        if isinstance(addr, ipaddress.IPv6Address) and addr.ipv4_mapped is not None:
            ipv4 = addr.ipv4_mapped
            try:
                net_ipv4 = ipaddress.IPv4Network(net_str, strict=False)
                if ipv4 in net_ipv4:
                    return True
            except ValueError:
                pass

        # Check the actual address against the network type
        try:
            if addr in network:
                return True
        except TypeError:
            # IPv4 address not directly comparable to IPv6 network and vice versa
            continue

    return False
